import math
def _min(km): return max(10, round(((12+km*0.85) if km<100 else (30+km*0.75))/5)*5)
def _km(a,b):
    R=6371; dla=math.radians(b[0]-a[0]); dlo=math.radians(b[1]-a[1]); h=math.sin(dla/2)**2+math.cos(math.radians(a[0]))*math.cos(math.radians(b[0]))*math.sin(dlo/2)**2
    return 2*R*math.asin(math.sqrt(h))
